-- Draft-only additive film contract. External providers remain external: HTTPS links only.
create table public.team_film (id uuid primary key default gen_random_uuid(), team_id uuid not null references public.teams(id) on delete cascade, title text not null, game_date date, opponent text, storage_path text, external_url text, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), check ((storage_path is null) <> (external_url is null)), check (external_url is null or external_url ~ '^https://'));
create table public.team_film_clips (id uuid primary key default gen_random_uuid(), film_id uuid not null references public.team_film(id) on delete cascade, title text not null, notes text, tags text[] not null default '{}', start_seconds numeric not null check(start_seconds>=0), end_seconds numeric not null check(end_seconds>start_seconds), created_by uuid not null references auth.users(id), created_at timestamptz not null default now());
create table public.team_film_playlists (id uuid primary key default gen_random_uuid(), team_id uuid not null references public.teams(id) on delete cascade, title text not null, topic text, sharing text not null default 'team_private' check(sharing in ('team_private','selected_staff')), created_by uuid not null references auth.users(id), created_at timestamptz not null default now());
create table public.team_film_playlist_clips (playlist_id uuid not null references public.team_film_playlists(id) on delete cascade, clip_id uuid not null references public.team_film_clips(id) on delete cascade, position integer not null check(position>=0), primary key(playlist_id,clip_id), unique(playlist_id,position));
alter table public.team_film enable row level security; alter table public.team_film_clips enable row level security; alter table public.team_film_playlists enable row level security; alter table public.team_film_playlist_clips enable row level security;
revoke all on public.team_film,public.team_film_clips,public.team_film_playlists,public.team_film_playlist_clips from anon;
-- Team-scoped policies will use existing capability matrix: film.view / film.edit. No platform bypass.
